from PIL import Image
img = Image.open('/app/output/final_poster.png')
# Check if title text exists by looking for dark pixels in the title region
found = False
for y in range(80, 160):
    for x in range(80, 800):
        p = img.getpixel((x,y))
        if p[0] < 80:
            if not found:
                print(f'First dark pixel in title area: ({x},{y}): {p}')
                found = True
            break
    if found:
        break

# Check subtitle region
found = False
for y in range(160, 250):
    for x in range(80, 800):
        p = img.getpixel((x,y))
        if p[0] < 100:
            if not found:
                print(f'First dark pixel in subtitle area: ({x},{y}): {p}')
                found = True
            break
    if found:
        break
"

